from typing import List

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        if max(nums) < 0:
            return max(nums)

        cur = best = nums[0]
        has_negative = nums[0] < 0

        for x in nums[1:]:
            has_negative |= x < 0
            cur = max(x, cur + x)
            best = max(best, cur)

        if not has_negative:
            return best

        prefix = 0
        floor = 0
        gains = {}
        max_gain = 0
        ans = best

        for x in nums:
            prefix += x

            if x < 0:
                gain = max(gains.get(x, 0), floor) - x
                gains[x] = gain
                max_gain = max(max_gain, gain)

            ans = max(ans, prefix + max_gain)

            floor = max(floor, -prefix)
            max_gain = max(max_gain, floor)

        return ans
